'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('zh-TW',{maximumFractionDigits:1});
const ICONS={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',chart:'M4 20V4 M4 20h17 M8 16v-4 M13 16V8 M18 16V5',battery:'M3 7h17v10H3Z M22 10v4 M7 10v4 M11 10v4 M15 10v4',settings:'M4 7h16 M4 17h16 M9 4v6 M16 14v6',device:'M4 4h16v12H4Z M8 21h8 M12 16v5',bell:'M6 17V9a6 6 0 0 1 12 0v8l2 2H4Z M10 22h4',check:'m5 12 4 4L19 6',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',power:'M13 2 4 14h7l-1 8 10-13h-7Z',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7Z m-5 9 3 3 5-5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',water:'M12 3s-7 8-7 12a7 7 0 0 0 14 0c0-4-7-12-7-12Z',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 10v6 M12 7v1',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',grid:'M4 21V8l8-5 8 5v13 M8 9h2 M14 9h2 M8 13h2 M14 13h2 M10 21v-5h4v5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[n]||ICONS.info}"/></svg>`;
const routes=[['overview','home','校園用電總覽'],['analysis','chart','統計報表'],['microgrid','battery','太陽能與備用電力'],['strategy','settings','省電與供電設定'],['safety','bell','提醒與帳號管理']];
const ROLES={
 admin:{name:'系統管理員',description:'可查看資料、調整所有供電設定、處理提醒，以及管理帳號。',permissions:['control','admin']},
 viewer:{name:'數據管理員',description:'可查看、查詢與下載資料；不能更改設定、設備狀態或處理紀錄。',permissions:[]},
 operator:{name:'能源管理員',description:'可查看資料、調整供電設定與處理提醒；帳號管理由系統管理員負責。',permissions:['control']}
};
const initial=()=>({version:1,scenario:'normal',role:'admin',userId:'u1',large:false,policy:'balanced',energySettings:EnergySettings.defaults(),alerts:structuredClone(DEMO.alerts),accounts:structuredClone(DEMO.accounts),logs:[{time:'2026/10/07 14:00',actor:'系統',text:'示範資料已準備完成。'}]});
let state=initial();try{const saved=JSON.parse(localStorage.getItem('nsysu-energy-demo-v1'));if(saved?.version===1)state={...state,...saved};}catch{}
state.energySettings=EnergySettings.restore(state.energySettings);delete state.reserve;delete state.threshold;delete state.devices;delete state.schedules;state.alerts=normalizeMicrogridAlerts(state.alerts);
let page=(location.hash.slice(1)||'overview'),activeTab='alerts',alertFilter='all',lastFocus=null;
function persist(){try{localStorage.setItem('nsysu-energy-demo-v1',JSON.stringify(state));}catch{}}
function log(text){state.logs.unshift({time:'2026/10/07 '+(DEMO.scenarios[state.scenario]?.time||'14:30'),actor:currentUser().name,text});state.logs=state.logs.slice(0,150);persist();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function scenario(){return DEMO.scenarios[state.scenario]||DEMO.scenarios.normal;}
function badge(text,tone='good'){return `<span class="pill ${tone}">${esc(text)}</span>`;}
function scenarioSelect(){return `<div class="field scenario-control"><label for="scenario">切換示範情境</label><select id="scenario" ${!permission()?'disabled aria-describedby="scenario-permission"':''}>${Object.entries(DEMO.scenarios).map(([k,v])=>`<option value="${k}" ${k===state.scenario?'selected':''}>${v.name}</option>`).join('')}</select>${!permission()?'<p id="scenario-permission" class="help-text">僅供查看，不能切換供電情境。</p>':''}</div>`;}
function heading(title,desc,extra=''){return `<div class="page-head"><div><div class="eyebrow">西子灣校區 · 示範資料</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function metric(label,value,unit,detail,ic='power'){return `<article class="card"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${fmt(value)}<span>${unit}</span></div><div class="metric-detail">${detail}</div></article>`;}
function hero(){const s=scenario();return `<section class="status-hero ${s.tone==='good'?'':s.tone}" aria-label="供電狀況"><div class="status-symbol">${icon(s.tone==='good'?'check':'info')}</div><div><h2>${s.title}</h2><p>${s.description}</p></div></section>`;}
function chart(values,labels,unit='kW'){const box=getComputedStyle($('#main')),available=$('#main').clientWidth-parseFloat(box.paddingLeft)-parseFloat(box.paddingRight),cw=page==='overview'&&innerWidth>1200?(available-20)*1.55/2.55:available,w=Math.max(240,Math.round(cw-(innerWidth<=450?32:innerWidth<=800?40:48))),h=260,p=52,max=Math.ceil(Math.max(...values)*1.15/100)*100||100;const points=values.map((v,i)=>[p+i*(w-2*p)/(Math.max(1,values.length-1)),h-p-v/max*(h-2*p)]);return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(unit)}用量趨勢；下方可展開數值表"><title>用量變化</title>${[0,.5,1].map(f=>`<line x1="${p}" y1="${h-p-f*(h-2*p)}" x2="${w-p}" y2="${h-p-f*(h-2*p)}" stroke="#dbe5eb"/><text x="${p-8}" y="${h-p-f*(h-2*p)+6}" text-anchor="end" class="chart-label">${fmt(max*f)}</text>`).join('')}<path d="M${points.map(v=>v.join(',')).join(' L')} L${w-p},${h-p} L${p},${h-p} Z" fill="#e4f2f7"/><polyline points="${points.map(v=>v.join(',')).join(' ')}" class="chart-line"/>${labels.map((l,i)=>i===0||i===labels.length-1||i%Math.ceil(labels.length/(w<500?2:5))===0?`<text x="${points[i][0]}" y="${h-12}" text-anchor="middle" class="chart-label">${esc(l)}</text>`:'').join('')}</svg></div>`;}
function alertDevice(a){return ReportData.assets.find(d=>d.id===a?.device&&['storage','pcs','pv','diesel'].includes(d.type));}
function microgridAlerts(){return state.alerts.filter(a=>alertDevice(a));}
function normalizeMicrogridAlerts(saved){
 const known=Array.isArray(saved)?saved:[];
 // New event IDs keep unrelated legacy notes from being attached to a different device.
 const mapped=known.map(a=>a.id==='a3'&&a.title==='電池室溫度曾經偏高'&&a.place==='國研儲能區'?{...a,category:'equipment',device:'ess-research'}:a).filter(a=>alertDevice(a));
 const result=DEMO.alerts.map(seed=>{const old=mapped.find(a=>a.id===seed.id&&a.device===seed.device);return old?{...seed,status:['new','working','done'].includes(old.status)?old.status:seed.status,note:typeof old.note==='string'?old.note:''}:{...seed};});
 for(const old of mapped)if(!result.some(a=>a.id===old.id))result.push({...old,category:'equipment'});
 return result;
}
function equipmentAlerts(){return microgridAlerts().filter(a=>a.status!=='done');}
function overview(){const s=scenario();return heading('今天，校園用電一目了然','先看供電狀況，再處理需要留意的事情。',scenarioSelect())+hero()+`<div class="grid metrics">${metric('四個示範區域累積用電',7840,'度電','固定參考紀錄：10/7 14:30','power')}${metric(state.scenario==='offline'?'太陽能最後提供':'太陽能目前提供',s.pv,'kW','來自兩處自用太陽能設備','sun')}${metric(state.scenario==='offline'?'電池最後剩餘':'備用電池還有',s.soc,'%','總儲電容量示範值：3,000 度','battery')}${metric('微電網設備異常待確認',equipmentAlerts().length,'件',state.scenario==='offline'?'暫時無法確認最新設備狀態':'請逐項查看提醒內容','bell')}</div><div class="grid split"><section class="card"><div class="card-head"><div><h2>電從哪裡來？</h2><p>國研微電網示範 · ${s.time}${state.scenario==='offline'?' 最後資料':''}</p></div><a href="#microgrid">查看備用供電</a></div>${sourceFlow()}</section><section class="card"><div class="card-head"><div><h2>先看這些提醒</h2><p>只顯示微電網設備尚未恢復的異常</p></div><a href="#safety">查看提醒中心</a></div>${equipmentAlerts().slice(0,2).map(a=>`<div class="alert-item">${badge(a.place,a.level)}<h3>${a.title}</h3><p class="help-text">${alertDevice(a).name}</p><p>${a.description}</p><button class="text-button" data-action="alert" data-id="${a.id}">查看如何處理</button></div>`).join('')||'<p>目前沒有待確認的微電網設備異常。</p>'}</section></div><div class="grid split section-space"><section class="card"><div class="card-head"><div><h2>今天的用電變化</h2><p>截至 14:30 的固定參考紀錄，不隨供電情境切換</p></div><a href="#analysis">查看用電紀錄</a></div>${chart(DEMO.history.slice(0,15),Array.from({length:15},(_,i)=>i+'時'))}<p class="chart-caption">上午用電逐漸增加，午間維持穩定。</p><details><summary>以數字表格查看</summary>${historyTable(DEMO.history.slice(0,15),'kW')}</details></section><section class="card"><div class="card-head"><div><h2>哪些地方用電較多？</h2><p>四個示範區域 · 固定紀錄截至 14:30</p></div></div>${DEMO.buildings.map(b=>`<div class="building-row"><div><strong>${b.name}</strong><p>${b.description}</p></div><div class="bar-track"><div class="bar-fill" style="width:${b.today/3240*100}%"></div></div><div class="building-value">${fmt(b.today)} 度</div></div>`).join('')}</section></div>`;}
function historyTable(values,unit='度'){return `<div class="table-wrap"><table><caption class="sr-only">示範數值資料</caption><thead><tr><th scope="col">時間</th><th scope="col">用量（${unit}）</th></tr></thead><tbody>${values.map((v,i)=>`<tr><td>${i}:00</td><td>${fmt(v)}</td></tr>`).join('')}</tbody></table></div>`;}
function openDialog(title,body,actions=''){pending=null;pendingReset=null;lastFocus=document.activeElement;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" data-action="close">關閉</button></div>${body}${actions?`<div class="actions">${actions}</div>`:''}`;$('#dialog').showModal();}
function closeDialog(){pending=null;pendingReset=null;$('#dialog').close();lastFocus?.isConnected&&lastFocus.focus();}
function help(){openDialog('第一次使用，從這裡開始',`<div class="form-grid"><p><strong>1. 先看首頁的供電說明。</strong><br>它會告訴您目前正常、需要留意，或暫時沒有新資料。</p><p><strong>2. 選擇想做的事情。</strong><br>左側五個入口可以查用電、看備用電力、設定省電方式及處理提醒。</p><p><strong>3. 先看影響，再確認操作。</strong><br>供電設定變更會先說明影響。重要研究設備受到保護。</p><p>「度電」是累積用電量；「kW」是當下用電大小；「電池剩餘」是還有多少電可用。</p><p class="note">這是示範版。所有操作只影響此瀏覽器裡的示範資料。</p></div>`);}
function analysis(){return renderReports();}
function microgrid(){const s=scenario();return heading('太陽能與備用電力','看懂現在由誰供電，以及備用設備是否準備好。',scenarioSelect())+hero()+`<div class="grid split"><section class="card"><div class="card-head"><div><h2>目前供電的方式</h2><p>${s.mode}</p></div>${badge(state.scenario==='offline'?'最後收到的資料':'示範時間 '+s.time,state.scenario==='offline'?'warn':'info')}</div>${sourceFlow()}<div class="note">停電時只保留國研重要用電與指定必要設備，不代表全校都能繼續供電。</div></section><section class="card"><div class="card-head"><h2>備用電池電量</h2>${badge((state.scenario==='offline'?'最後紀錄：':'')+(s.soc<20?'電量偏低':'電量充足'),s.soc<20?'danger':'good')}</div><div class="metric-value">${s.soc}<span>% 剩餘電量</span></div><div class="progress" role="progressbar" aria-label="電池剩餘電量" aria-valuenow="${s.soc}" aria-valuemin="0" aria-valuemax="100"><span style="width:${s.soc}%;background:${s.soc<20?'var(--red)':'var(--green)'}"></span></div><div class="device-stat"><span>剩餘儲電量</span><strong>${fmt(3000*s.soc/100)} 度</strong></div><div class="device-stat"><span>電池健康程度</span><strong>${state.scenario==='offline'?'最後紀錄：':''}98%</strong></div><div class="device-stat"><span>電池室溫度</span><strong>${state.scenario==='offline'?'最後紀錄：':''}26°C</strong></div><div class="device-stat"><span>煙霧及火警偵測</span><strong>${state.scenario==='offline'?'最後回報：':''}沒有異常</strong></div><p class="help-text">可供電多久，還要看當時用了多少電；剩餘電量不是供電時間保證。${state.scenario==='offline'?'這些狀態皆為最後紀錄。':''}</p></section></div><div class="grid device-grid section-space"><section class="card"><h2>太陽能發電</h2><p class="device-location">國研屋頂與海工停車場</p><div class="device-stat"><span>國研屋頂規劃容量</span><strong>135 kWp</strong></div><div class="device-stat"><span>海工停車場規劃容量</span><strong>295 kWp</strong></div><div class="device-stat"><span>今天示範發電量</span><strong>1,650 度</strong></div><p class="help-text">kWp 表示設備規模；實際發電會隨陽光改變。</p></section><section class="card"><h2>備用電池設備</h2><p class="device-location">國研大樓旁儲能區</p><div class="device-stat"><span>規劃儲電容量</span><strong>至少 3,000 度</strong></div><div class="device-stat"><span>規劃供電能力</span><strong>至少 1,200 kW</strong></div><div class="device-stat"><span>${state.scenario==='offline'?'最後回報狀態':'目前狀態'}</span><strong>${s.battery<0?'正在充電，把電存起來':s.battery>0?'正在協助供電':s.soc<10?'低電量保護中':'準備待命'}</strong></div></section><section class="card"><h2>柴油發電機</h2><p class="device-location">國研大樓既有備用機組</p><div class="device-stat"><span>設備供電能力</span><strong>400 kW</strong></div><div class="device-stat"><span>${state.scenario==='offline'?'最後紀錄提供':'現在提供'}</span><strong>${s.generator} kW</strong></div><div class="device-stat"><span>${state.scenario==='offline'?'最後回報狀態':'目前狀態'}</span><strong>${s.generator?'供應必要用電':'準備待命'}</strong></div><p class="help-text">由現場設備依安全條件啟動，這裡不提供直接強制啟動。</p></section></div><details class="card section-space"><summary>設備容量與監看範圍</summary><p>135 kWp 與 295 kWp 為本案更新後的規劃容量。既有國研躉售太陽能 51.92 kWp 另行監看，未算入上方供電合計。風雨球場的未來規劃也未算入。</p><p>GCB6 涉及國研、社科院、管理學院及 A 水池等區域。停電保留範圍依情境縮小；電池不足情境僅示範國研必要用電 240 kW。</p><p class="help-text">設備健康、溫度、發電量與狀態皆是示範資料，並非校園即時量測。</p></details>`;}
const policies={balanced:{title:'平常省電',text:'平常優先使用太陽能；需量達到門檻時，再讓電池協助供電。',items:['適合一般上課與辦公日','遵守下方併聯電量範圍','重要研究設備照常供電']},saving:{title:'用電多時幫忙',text:'依設定的契約容量與啟動百分比，讓電池協助降低用電尖峰。',items:['到達設定門檻時啟動需量支援','電量到下限就停止電池供電','不會隨意關閉重要研究設備']},backup:{title:'優先保留備用電',text:'平常暫停需量支援，把電池留給停電時使用。',items:['平常不因需量偏高而啟動電池','兩組電量上下限設定保持不變','停電時改用孤島電量範圍']}};
function permission(kind='control'){const u=currentUser();return !!u.active&&!!ROLES[u.role]?.permissions.includes(kind);}
function emergency(){return ['outage','low'].includes(state.scenario);}
function blocked(){return state.scenario==='offline'||emergency()||!permission();}
function strategy(){return heading('省電與供電設定','分別設定平常與停電時的電池範圍，再決定何時請電池幫忙。',scenarioSelect())+`${emergency()?'<div class="note warn">停電示範由現場接手供電，暫停送出新的供電設定。</div>':''}${state.scenario==='offline'?'<div class="note warn">目前收不到新資料，暫時不能送出新設定。</div>':''}${!permission()?'<p class="note">您目前是數據管理員，可以閱讀與試算；設定變更請交由系統管理員或能源管理員。</p>':''}${renderEnergySettings()}<section class="section-space"><h2>選擇平常的供電策略</h2><div class="grid strategy-grid section-space">${Object.entries(policies).map(([id,p])=>`<article class="card strategy-card ${state.policy===id?'selected':''}">${badge(state.policy===id?'目前使用':'可選方式',state.policy===id?'good':'neutral')}<h3 class="strategy-title">${p.title}</h3><p>${p.text}</p><ul class="list-clean">${p.items.map(i=>`<li>${i}</li>`).join('')}</ul><button class="${state.policy===id?'':'primary'}" data-action="policy" data-id="${id}" ${blocked()||state.policy===id?'disabled':''}>${state.policy===id?'正在使用':'改用這個方式'}</button></article>`).join('')}</div></section>${renderEnergyTrial()}<section class="card section-space"><h2>最近的設定紀錄</h2>${logList(state.logs.filter(l=>/方式|設定/.test(l.text)).slice(0,5))}<p class="note">重要研究設備持續受到保護。雲端設定仍須由現場設備檢查，並依實際電量、設備狀況及供電需要執行。</p></section>`;}
function logList(logs){return logs.length?`<div class="timeline">${logs.map(l=>`<div><strong>${esc(l.text)}</strong><p>${esc(l.time)} · ${esc(l.actor)}</p></div>`).join('')}</div>`:'<p class="help-text">尚未有新的操作紀錄。</p>';}
function safety(){const tabs=[['alerts','待處理提醒'],['accounts','使用者與權限'],['security','系統安全與紀錄']];let content='';if(activeTab==='alerts'){const list=microgridAlerts().filter(a=>alertFilter==='all'||a.status===alertFilter);content=`<section class="card"><p class="note">提醒範圍：儲能電池、PCS（電力轉換設備）、太陽能及柴油發電機。以下均為示範設備異常。</p><div class="toolbar"><div class="field"><label for="alert-filter">想查看哪些提醒？</label><select id="alert-filter">${[['all','全部提醒'],['new','還沒處理'],['working','已安排處理'],['done','已恢復／已完成']].map(x=>`<option value="${x[0]}" ${alertFilter===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><button data-action="export-alerts">下載提醒清單</button></div>${list.map(a=>`<article class="alert-item"><div class="card-head"><div>${badge({new:'還沒處理',working:'已安排處理',done:'已恢復'}[a.status],a.status==='done'?'good':a.level)}<h2>${a.title}</h2></div><span class="muted">${a.time} · ${a.place}</span></div><p class="help-text">${alertDevice(a).name} · ${ReportData.types[alertDevice(a).type]}</p><p>${a.description}</p>${a.note?`<p class="note">處理紀錄：${esc(a.note)}</p>`:''}<button data-action="alert" data-id="${a.id}">${a.status==='done'?'查看處理紀錄':permission()?'查看並安排處理':'查看提醒內容'}</button></article>`).join('')||'<div class="empty">目前沒有這個類型的提醒。</div>'}</section>`;}else if(activeTab==='accounts'){content=!permission('admin')?`<section class="card"><h2>帳號管理由系統管理員負責</h2><p class="section-space">您目前是${roleName(currentUser().role)}，不能新增、修改、停用或恢復帳號。下方可查看各角色的操作範圍。</p></section>${roleCards()}`:`<section class="card"><div class="card-head"><div><h2>誰可以使用這個系統？</h2><p>示範帳號只存於此瀏覽器，不是正式登入帳號。</p></div><button class="primary" data-action="account-add" ${!permission('admin')?'disabled':''}>新增示範使用者</button></div>${state.accounts.map(u=>`<div class="account-row"><div class="account-info"><span class="avatar" aria-hidden="true">${esc(u.name[0])}</span><div><h3>${esc(u.name)}</h3><p>${roleName(u.role)} · ${u.active?'可以使用':'已暫停使用'}</p></div></div><div class="actions"><button data-action="account-edit" data-id="${u.id}" ${!permission('admin')||u.id==='u1'||u.id===state.userId?'disabled':''}>調整權限</button><button data-action="account-toggle" data-id="${u.id}" ${!permission('admin')||u.id==='u1'||u.id===state.userId?'disabled':''}>${u.active?'暫停使用':'恢復使用'}</button></div></div>`).join('')}<p class="help-text">目前的使用者與預設系統管理員受到保護，避免操作後失去管理權限。</p></section>${roleCards()}`;}else{content=`<div class="grid security-grid"><section class="card"><h2>資料連線</h2><p class="section-space">${badge(state.scenario==='offline'?'暫時無法更新':'示範連線正常',state.scenario==='offline'?'warn':'good')}</p><p class="help-text">最後收到：${scenario().time}。這是模擬的資料狀態。</p></section><section class="card"><h2>資料備份</h2><p class="section-space">${badge('示範備份已完成')}</p><p class="help-text">示範紀錄：今天 06:00 完成。未連接正式資料庫或 NAS。</p></section><section class="card"><h2>使用權限</h2><p class="section-space">${badge(roleName(state.role),'info')}</p><p class="help-text">${roleDescription()}</p></section></div><section class="card section-space"><div class="card-head"><div><h2>最近做過哪些操作？</h2><p>保留設定變更、設備操作與提醒處理紀錄。</p></div><button data-action="export-logs">下載操作紀錄</button></div>${logList(state.logs.slice(0,20))}</section><section class="card section-space"><h2>正式上線前的安全檢查</h2><p class="help-text">這裡是規劃狀態，不代表已完成認證或安全檢測。</p><div class="inline-summary"><span>檢查網站、資料介面與主機漏洞</span>${badge('待正式系統驗證','neutral')}</div><div class="inline-summary"><span>修補中度以上風險並重新檢查</span>${badge('待正式系統驗證','neutral')}</div><div class="inline-summary"><span>驗證備份還原與第三方接手</span>${badge('待正式系統驗證','neutral')}</div></section>`;}return heading('提醒與帳號管理','處理需要留意的事情，也能查看誰做過哪些操作。')+`<div class="tabs" role="tablist" aria-label="提醒與帳號功能">${tabs.map(([k,n])=>`<button role="tab" aria-selected="${activeTab===k}" data-action="safety-tab" data-id="${k}">${n}</button>`).join('')}</div><div role="tabpanel">${content}</div>`;}
function currentUser(){return state.accounts.find(u=>u.id===state.userId&&u.active)||{id:'',name:'尚未選擇有效示範帳號',role:'viewer',active:false};}
function roleName(r){return ROLES[r]?.name||'數據管理員';}
function roleDescription(){return currentUser().active?ROLES[currentUser().role]?.description||ROLES.viewer.description:'目前沒有有效示範帳號，僅能查看資料。可使用右上方「切換示範角色」繼續體驗。';}
function roleSummary(){return `<section class="role-status" aria-label="目前角色與操作範圍">${badge('目前角色：'+roleName(currentUser().role),'info')}<p>${roleDescription()}</p></section>`;}
function roleCards(){return `<section class="card section-space"><h2>三種角色，可以做哪些事？</h2><div class="grid security-grid section-space">${Object.entries(ROLES).map(([key,r])=>`<article class="role-card ${currentUser().role===key?'current':''}"><h3>${r.name}</h3><p>${r.description}</p></article>`).join('')}</div></section>`;}
function setDemoScenario(value){if(!permission())throw Error('數據管理員只能查看資料，不能切換供電情境。');if(!Object.hasOwn(DEMO.scenarios,value))throw Error('請選擇有效的示範情境。');state.scenario=value;log('供電示範情境切換為「'+scenario().name+'」。');render();return {demo:true,scenario:state.scenario,title:scenario().title};}
function render(){state.userId=currentUser().id;state.role=currentUser().role;if(!routes.some(r=>r[0]===page))page='overview';document.documentElement.classList.toggle('large-text',state.large);$('#font-button').textContent=state.large?'恢復標準大字':'字體再放大';$('#font-button').setAttribute('aria-pressed',String(state.large));$('#current-role').textContent=roleName(state.role);$('[data-action=role]').setAttribute('aria-label',currentUser().name+'，'+roleName(state.role)+'，切換示範角色');$$('[data-action=reset]').forEach(b=>{b.disabled=!permission();b.title=permission('admin')?'恢復全部示範資料':permission()?'恢復供電設定示範，保留帳號和操作紀錄':'數據管理員只能查看資料，不能重設示範';});$('#avatar').textContent=currentUser().name.slice(0,1);$('#nav').innerHTML=routes.map(r=>`<a class="nav-item" href="#${r[0]}" ${r[0]===page?'aria-current="page"':''}>${icon(r[1])}<span class="nav-full">${r[2]}</span><span class="nav-short">${{overview:"用電總覽",analysis:"統計報表",microgrid:"太陽能與電池",strategy:"省電與供電",safety:"提醒與帳號"}[r[0]]}</span></a>`).join('');$('#breadcrumb').textContent='中山大學雲端能源管理系統';document.title=routes.find(r=>r[0]===page)[2]+'｜中山大學雲端能源管理系統';const views={overview,analysis,microgrid,strategy,safety};$('#main').innerHTML=roleSummary()+views[page]();}
document.addEventListener('change',e=>{const id=e.target.id,v=e.target.value;if(id==='scenario'){try{setDemoScenario(v);toast('已切換示範情境：'+scenario().name);}catch(error){e.target.value=state.scenario;toast(error.message);}}if(id==='alert-filter'){alertFilter=v;render();}});
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const b=e.target.closest('[data-action]');if(b&&!b.disabled)handleAction(b.dataset.action,b.dataset.id,b);});
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open){pending=null;pendingReset=null;if(lastFocus?.isConnected)lastFocus.focus();}});
$('#dialog').addEventListener('cancel',()=>{pending=null;pendingReset=null;});
let pending=null,pendingReset=null;
function authorize(admin=false){if(!permission(admin?'admin':'control')){toast(admin?'帳號管理僅限系統管理員操作。':'數據管理員只能查看與下載資料，不能更改設定或處理紀錄。');return false;}return true;}
function connected(){if(emergency()){toast('停電示範期間由現場保留必要供電，暫停送出供電設定。');return false;}if(state.scenario==='offline'){toast('目前沒有新資料，暫時不能送出設定。');return false;}return true;}
function confirmOperation(title,summary,fn,admin=false){openDialog(title,`<div class="result-box">${summary}</div><p class="help-text">確認後會模擬現場檢查。操作只影響示範資料。</p>`,`<button data-action="close">先不要更改</button><button class="primary" data-action="confirm">確認送出</button>`);pending={fn,admin,userId:currentUser().id};}
function exportCsv(name,rows){const clean=v=>{let x=String(v??'');if(/^[=+@\-]/.test(x))x="'"+x;return '"'+x.replaceAll('"','""')+'"';};const body='\ufeff'+rows.map(r=>r.map(clean).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([body],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('已下載示範資料，可用 Excel 開啟。');}
function accountForm(id){if(!authorize(true))return;const u=state.accounts.find(x=>x.id===id);if(u?.id==='u1'||u?.id===state.userId)return;openDialog(u?'調整使用者權限':'新增示範使用者',`<form id="account-form" class="form-grid" data-id="${u?.id||''}"><div class="field"><label for="account-name">使用者名稱</label><input id="account-name" name="name" required maxlength="20" minlength="2" value="${esc(u?.name||'')}" placeholder="例如：張維護員"></div><div class="field"><label for="account-role">可以做哪些事？</label><select id="account-role" name="role">${Object.entries(ROLES).map(([key,r])=>[key,r.name]).map(([k,n])=>`<option value="${k}" ${(u?.role||'viewer')===k?'selected':''}>${n}</option>`).join('')}</select><p class="help-text">數據管理員只能看資料；能源管理員可調整供電設定；系統管理員還能管理帳號。</p></div><p class="help-text">這只建立此瀏覽器中的示範記錄，不會寄出邀請或建立正式帳號。</p><p class="error" id="account-error" role="alert"></p><button class="primary" type="submit">儲存示範使用者</button></form>`);}
function alertDialog(id){const a=microgridAlerts().find(x=>x.id===id);if(!a)return;openDialog(a.title,`${badge(a.place,a.level)}<p class="help-text section-space">${alertDevice(a).name} · ${ReportData.types[alertDevice(a).type]}</p><p class="section-space">${a.description}</p><p class="help-text">發生時間：今天 ${a.time}</p>${!permission()?'<p class="note">您可以查看提醒；新增或修改處理紀錄，請交由系統管理員或能源管理員操作。</p>':''}${a.status==='done'?`<div class="note">${esc(a.note)}</div>`:`<form id="alert-form" data-id="${a.id}" class="form-grid section-space"><div class="field"><label for="alert-note">已安排誰處理？或有什麼需要記錄？</label><textarea id="alert-note" name="note" required maxlength="300" ${!permission()?'disabled':''} placeholder="例如：已安排維護人員檢查儲能設備">${esc(a.note)}</textarea></div><p class="help-text">記錄處理情形，不代表設備故障已消除。</p><p class="error" id="alert-error" role="alert"></p><button type="submit" class="primary" ${!permission()?'disabled':''}>記錄為「已安排處理」</button></form>`}`);}
function handleAction(a,id,b){
 if(a==='close'){pending=null;closeDialog();}
 if(a==='help')help();
 if(a==='font'){state.large=!state.large;persist();render();$('#font-button').focus();}
 if(a==='role')openDialog('體驗角色',`<p>這是展示用的角色體驗工具，不會修改任何帳號的權限，也不是正式登入。</p><p class="help-text">目前使用者：${esc(currentUser().name)} · ${roleName(currentUser().role)}</p><div class="stack section-space">${state.accounts.filter(u=>u.active).map(u=>`<button data-action="switch-role" data-id="${u.id}" class="${state.userId===u.id?'primary':''}">${esc(u.name)} · ${roleName(u.role)}<span class="role-option-detail">${ROLES[u.role]?.description||ROLES.viewer.description}</span></button>`).join('')}</div>`);
 if(a==='switch-role'){clearEnergyDraft();const u=state.accounts.find(u=>u.id===id&&u.active);if(!u)return;state.userId=u.id;state.role=u.role;persist();closeDialog();render();toast('已切換為'+u.name+'，權限為'+roleName(u.role));}
 if(a==='alert')alertDialog(id);
 if(a==='safety-tab'){activeTab=id;render();$(`[data-action="safety-tab"][data-id="${id}"]`)?.focus();}
 if(a==='export-alerts')exportCsv('中山大學_微電網設備提醒.csv',[['發生時間','地點','設備名稱','設備種類','提醒','狀態','處理紀錄'],...microgridAlerts().filter(x=>alertFilter==='all'||x.status===alertFilter).map(x=>[x.time,x.place,alertDevice(x).name,ReportData.types[alertDevice(x).type],x.title,{new:'還沒處理',working:'已安排處理',done:'已恢復'}[x.status],x.note])]);
 if(a==='export-logs')exportCsv('中山大學_示範操作紀錄.csv',[['時間','操作人員','內容'],...state.logs.map(x=>[x.time,x.actor,x.text])]);
 if(a==='print')window.print();
 if(a==='policy'){if(!authorize()||!connected()||!policies[id])return;confirmOperation('改用「'+policies[id].title+'」？',`<p>${policies[id].text}</p><p>兩組電池上下限與契約容量設定保持不變。重要研究設備仍受到保護。</p>`,()=>{state.policy=id;log('供電方式改為「'+policies[id].title+'」。');return '已改用「'+policies[id].title+'」，示範策略已儲存。';});}
 if(a==='account-add')accountForm();if(a==='account-edit')accountForm(id);
 if(a==='account-toggle'){const u=state.accounts.find(x=>x.id===id);if(!u||(u.id==='u1'||u.id===state.userId)||!authorize(true))return;confirmOperation((u.active?'暫停':'恢復')+'這位使用者？',`<p>${esc(u.name)} · ${roleName(u.role)}</p><p>只會變更示範帳號的狀態。</p>`,()=>{u.active=!u.active;log(esc(u.name)+'的示範帳號已'+(u.active?'恢復':'暫停')+'。');return '示範使用者狀態已更新。';},true);}
 if(a==='confirm'){if(!pending||pending.userId!==currentUser().id||!authorize(pending.admin))return;if(!pending.admin&&!connected())return;const p=pending;pending=null;const out=p.fn();persist();closeDialog();render();openDialog('已完成示範操作',`<div class="note">${esc(out)}</div><div class="timeline"><div><strong>1. 設定已送出</strong><p>系統收到這次示範操作。</p></div><div><strong>2. 條件檢查通過</strong><p>已確認權限及允許變更的範圍。</p></div><div><strong>3. 結果已回報</strong><p>已更新示範資料並留下操作紀錄。</p></div></div>`);}
 if(a==='reset'){if(!authorize())return;const all=permission('admin');openDialog('重新開始示範？',all?'<p>會清除這個瀏覽器內新增的示範設定、帳號和處理紀錄，回到最初的示範資料。</p>':'<p>會恢復供電設定與提醒的初始示範資料。</p><p>所有帳號、角色權限、目前使用者及操作紀錄都會保留。</p>','<button data-action="close">保留目前資料</button><button class="danger-button" data-action="reset-confirm">重設示範資料</button>');pendingReset={all,userId:currentUser().id};}
 if(a==='discard-energy'){if(!authorize())return;clearEnergyDraft();render();toast('已回到目前儲存的設定。');}
 if(a==='reset-confirm'){if(!pendingReset||pendingReset.userId!==currentUser().id||!authorize(pendingReset.all))return;const keep=pendingReset.all?null:{accounts:state.accounts,userId:state.userId,role:currentUser().role,large:state.large,logs:state.logs};reportActiveTab='usage';islandState=initialIslandState();reportDraft=ReportData.defaults();reportApplied=null;reportError='';reportPage=0;reportEventPage=0;clearEnergyDraft();energyTrial={mode:'grid',soc:72,demand:950};state=initial();if(keep){Object.assign(state,keep);log('已重設供電設定與提醒的示範資料；帳號及權限保持不變。');}persist();activeTab='alerts';closeDialog();render();toast(keep?'已恢復供電設定示範，帳號、權限及操作紀錄已保留。':'已恢復最初的示範資料。');}
}
document.addEventListener('keydown',e=>{if(e.target.matches('[data-action="safety-tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const keys=['alerts','accounts','security'],n=keys.indexOf(activeTab);activeTab=e.key==='Home'?keys[0]:e.key==='End'?keys[2]:keys[(n+(e.key==='ArrowRight'?1:2))%3];render();$(`[data-id="${activeTab}"][role="tab"]`)?.focus();}});
document.addEventListener('submit',e=>{const f=e.target;if(!['settings-form','account-form','alert-form'].includes(f.id))return;e.preventDefault();const values=Object.fromEntries(new FormData(f));
 if(f.id==='settings-form'){saveEnergySettings(values);}
 if(f.id==='alert-form'){if(!authorize())return;const a=microgridAlerts().find(x=>x.id===f.dataset.id),note=String(values.note||'').trim();if(!a)return;if(!note){$('#alert-error').textContent='請簡單寫下已安排的處理方式。';return;}a.note=note;a.status='working';log('已安排處理「'+a.title+'」。');closeDialog();render();toast('已記錄處理情形；設備狀態仍需現場確認。');}
 if(f.id==='account-form'){if(!authorize(true))return;const name=String(values.name||'').trim();if(name.length<2||name.length>20||state.accounts.some(x=>x.name===name&&x.id!==f.dataset.id)||!['admin','operator','viewer'].includes(values.role)){$('#account-error').textContent='名稱請填 2–20 個字，並避免與其他使用者重複。';return;}const old=state.accounts.find(x=>x.id===f.dataset.id);if(old?.id==='u1'||old?.id===state.userId)return;if(old)Object.assign(old,{name,role:values.role});else state.accounts.push({id:'u'+Date.now(),name,role:values.role,active:true});log('已儲存「'+name+'」的示範帳號與權限。');closeDialog();render();toast('示範使用者已儲存。');}
});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(!$('#dialog').open)render();},120);});
