if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_energy_demo_status',title:'查看能源示範狀況',description:'Read the currently displayed demo scenario and power balance. These are simulated values, never live campus data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({demo:true,scenario:state.scenario,...scenario(),role:roleName(state.role)})},{name:'set_energy_demo_scenario',title:'切換能源示範情境',description:'Switch the visible demo scenario only; does not operate real equipment.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(DEMO.scenarios)}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='scenario')||!Object.hasOwn(DEMO.scenarios,input.scenario))throw Error('Unknown demo scenario');return setDemoScenario(input.scenario);}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
